package com.portfolio.assetory.review.controller;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid; import com.portfolio.assetory.global.auth.CurrentUserId; import com.portfolio.assetory.global.response.ApiResponse; import com.portfolio.assetory.review.dto.request.*; import com.portfolio.assetory.review.dto.response.*; import com.portfolio.assetory.review.service.ReviewCommandService;
@RestController @RequestMapping("/api/reviews") public class MyReviewController { private final ReviewCommandService service; public MyReviewController(ReviewCommandService service){this.service=service;} @PostMapping public ResponseEntity<ApiResponse<MyReviewResponse>> create(@CurrentUserId Long userId,@RequestParam Long productId,@Valid @RequestBody CreateReviewRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success(service.create(userId,productId,request)));} @PatchMapping("/{reviewId}") public ResponseEntity<ApiResponse<MyReviewResponse>> update(@CurrentUserId Long userId,@PathVariable Long reviewId,@Valid @RequestBody UpdateReviewRequest request){return ResponseEntity.ok(ApiResponse.success(service.update(userId,reviewId,request)));} @DeleteMapping("/{reviewId}") public ResponseEntity<ApiResponse<Void>> delete(@CurrentUserId Long userId,@PathVariable Long reviewId){service.delete(userId,reviewId);return ResponseEntity.ok(ApiResponse.success("후기가 삭제되었습니다.",null));} @GetMapping("/me") public ResponseEntity<ApiResponse<MyReviewListResponse>> list(@CurrentUserId Long userId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ResponseEntity.ok(ApiResponse.success(service.list(userId,page,size)));} }
